using Dabbler.Api.Querying;
using AcmeCoffeeOnline.Api.Data;
using AcmeCoffeeOnline.Shared.DTOs;
using AcmeCoffeeOnline.Shared.Models;
using Microsoft.EntityFrameworkCore;
using System.Reflection;

namespace AcmeCoffeeOnline.Api.Services;

/// <summary>
/// EF Core-backed implementation of <see cref="ISupplierService"/>.
///
/// Generated by the dabbler-crud-service template. Edit-points the consumer typically owns:
///   - <see cref="MapToDto"/> / <see cref="MapToEntity"/> / <see cref="CopyTo"/> — adjust property
///     copies, or replace with AutoMapper / Mapster if the consuming app uses a mapper.
///   - <see cref="ApplyScope"/> — narrow the IQueryable for multi-tenant / organization scoping
///     before <see cref="QueryAsync"/> and <see cref="GetByIdAsync"/> evaluate the filter.
///   - <see cref="ClampPaging"/> — adjust page-size bounds per product policy.
/// The generic <c>ApplyGridCompositeFilter</c> / <c>ApplyGridQuerySorts</c> calls handle
/// per-property filter/sort dispatch via expression trees, so no per-property scaffold is needed.
/// </summary>
public class SupplierService : ISupplierService
{
    private readonly AcmeCoffeeDbContext _db;

    public SupplierService(AcmeCoffeeDbContext db)
    {
        _db = db;
    }

    public async Task<GridQueryResponse<SupplierDto>> QueryAsync(
        GridQueryRequest request,
        CancellationToken cancellationToken = default)
    {
        ClampPaging(request, out var pageIndex, out var pageSize);

        var query = ApplyScope(_db.Suppliers.AsNoTracking());
        query = query.ApplyGridCompositeFilter(request.Filter);
        query = query.ApplyGridQuerySorts(request.Sorts);

        var total = await query.CountAsync(cancellationToken);
        var items = await query
            .Skip(pageIndex * pageSize)
            .Take(pageSize)
            .ToListAsync(cancellationToken);

        return new GridQueryResponse<SupplierDto>
        {
            Items = items.Select(MapToDto).ToList(),
            TotalCount = total,
            PageIndex = pageIndex,
            PageSize = pageSize,
        };
    }

    public async Task<SupplierDto?> GetByIdAsync(int id, CancellationToken cancellationToken = default)
    {
        var entity = await ApplyScope(_db.Suppliers.AsNoTracking())
            .FirstOrDefaultAsync(e => e.Id.Equals(id), cancellationToken);
        return entity is null ? null : MapToDto(entity);
    }

    public async Task<SupplierDto> CreateAsync(SupplierDto dto, CancellationToken cancellationToken = default)
    {
        var entity = MapToEntity(dto);
        _db.Suppliers.Add(entity);
        await _db.SaveChangesAsync(cancellationToken);
        return MapToDto(entity);
    }

    public async Task<SupplierDto?> UpdateAsync(int id, SupplierDto dto, CancellationToken cancellationToken = default)
    {
        var existing = await ApplyScope(_db.Suppliers)
            .FirstOrDefaultAsync(e => e.Id.Equals(id), cancellationToken);
        if (existing is null) return null;

        CopyTo(dto, existing);
        await _db.SaveChangesAsync(cancellationToken);
        return MapToDto(existing);
    }

    public async Task<bool> DeleteAsync(int id, CancellationToken cancellationToken = default)
    {
        var existing = await ApplyScope(_db.Suppliers)
            .FirstOrDefaultAsync(e => e.Id.Equals(id), cancellationToken);
        if (existing is null) return false;

        _db.Suppliers.Remove(existing);
        await _db.SaveChangesAsync(cancellationToken);
        return true;
    }

    // ── Customization seams ────────────────────────────────────────────────

    /// <summary>
    /// Narrows the IQueryable before filter / sort / paging evaluation.
    /// Replace with a per-organization / per-tenant / per-row-restriction filter
    /// when the consuming app's authorization model requires it.
    /// </summary>
    protected virtual IQueryable<Supplier> ApplyScope(IQueryable<Supplier> query) => query;

    /// <summary>
    /// Returns the property names the default mapping helpers should NEVER copy from a DTO
    /// onto an entity. The primary-key column 'Id' is excluded by default so:
    ///   (a) CreateAsync cannot accept client-supplied keys (no explicit key injection),
    ///   (b) UpdateAsync cannot attempt to change the tracked entity's key via a DTO mismatch.
    /// Override to add server-controlled columns (CreatedAt, ModifiedBy, RowVersion, …) the
    /// consumer wants protected from client mutation.
    /// </summary>
    protected virtual ISet<string> NonCopyablePropertiesFromDto { get; } =
        new HashSet<string>(StringComparer.Ordinal) { "Id" };

    /// <summary>
    /// Projects an EF entity onto its DTO by copying same-named public read/write properties.
    /// Override to customise (omit server-controlled columns, flatten nested data, etc.) or
    /// replace the body with an AutoMapper / Mapster call.
    /// </summary>
    protected virtual SupplierDto MapToDto(Supplier entity)
    {
        var dto = new SupplierDto();
        CopySameNamedProperties(source: entity, destination: dto, skipDestNames: null);
        return dto;
    }

    /// <summary>
    /// Builds a new EF entity from a DTO for inserts by copying same-named public read/write
    /// properties, excluding <see cref="NonCopyablePropertiesFromDto"/> (PK by default).
    /// Override to set server-controlled columns (timestamps, audit fields, derived keys)
    /// before the entity is added.
    /// </summary>
    protected virtual Supplier MapToEntity(SupplierDto dto)
    {
        var entity = new Supplier();
        CopySameNamedProperties(source: dto, destination: entity, skipDestNames: NonCopyablePropertiesFromDto);
        return entity;
    }

    /// <summary>
    /// Copies updatable fields from the DTO onto a tracked EF entity for PUT semantics,
    /// excluding <see cref="NonCopyablePropertiesFromDto"/> so the primary key cannot be
    /// changed via DTO/route mismatch.
    /// </summary>
    protected virtual void CopyTo(SupplierDto dto, Supplier entity)
    {
        CopySameNamedProperties(source: dto, destination: entity, skipDestNames: NonCopyablePropertiesFromDto);
    }

    /// <summary>
    /// Helper for MapToDto / MapToEntity / CopyTo: copies values of public read/write
    /// properties whose names match between source and destination. Property names listed
    /// in <paramref name="skipDestNames"/> are not written to the destination.
    /// </summary>
    private static void CopySameNamedProperties(object source, object destination, ISet<string>? skipDestNames)
    {
        var sourceProps = source.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance);
        var destProps = destination.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .Where(p => p.CanWrite)
            .ToDictionary(p => p.Name, StringComparer.Ordinal);
        foreach (var sp in sourceProps)
        {
            if (!sp.CanRead) continue;
            if (skipDestNames is not null && skipDestNames.Contains(sp.Name)) continue;
            if (!destProps.TryGetValue(sp.Name, out var dp)) continue;
            if (!dp.PropertyType.IsAssignableFrom(sp.PropertyType)) continue;
            dp.SetValue(destination, sp.GetValue(source));
        }
    }

    private static void ClampPaging(GridQueryRequest request, out int pageIndex, out int pageSize)
    {
        pageIndex = request.PageIndex < 0 ? 0 : request.PageIndex;
        pageSize = Math.Clamp(request.PageSize, 1, 100);
    }
}
